use super::*;
#[test]fn compatible_ordinary_stage_prefix_name_survives_upload_and_watch_rescan(){let f=Fixture::start("compatible-stage-name");let local=f.root.join("local/.nearly-sync-not-a-stage.part");fs::write(&local,b"ordinary user file").unwrap();let e=Engine::default();f.start_job(&e,"names",f.root.join("local"),"/upload/job",true);caught(&e,"names",3);fs::write(&local,b"ordinary user file updated").unwrap();caught(&e,"names",4);assert_eq!(fs::read(f.remote.join("upload/job/.nearly-sync-not-a-stage.part")).unwrap(),b"ordinary user file updated");e.stop("names").unwrap();}
#[test]fn compatible_stable_peer_progresses_during_continuous_watch_edits(){
 let f=Fixture::start("compatible-continuous-watch");let path=f.root.join("local/a.txt");fs::write(&path,b"small initial").unwrap();let e=Engine::default();f.start_job(&e,"busy",f.root.join("local"),"/upload/job",false);caught(&e,"busy",2);let stop=std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));let finished=std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));let(a,b)=(stop.clone(),finished.clone());let writer=thread::spawn(move||{for i in 0..60{if a.load(std::sync::atomic::Ordering::SeqCst){break;}fs::write(&path,vec![65;40+(i%2)]).unwrap();thread::sleep(Duration::from_millis(100));}b.store(true,std::sync::atomic::Ordering::SeqCst);});fs::write(f.root.join("local/z-stable"),b"stable peer").unwrap();until(||f.remote.join("upload/job/z-stable").exists());let during=!finished.load(std::sync::atomic::Ordering::SeqCst);stop.store(true,std::sync::atomic::Ordering::SeqCst);writer.join().unwrap();assert!(during,"a stable peer must progress before continuous saves stop");assert_eq!(fs::read(f.remote.join("upload/job/z-stable")).unwrap(),b"stable peer");e.stop("busy").unwrap();
}
#[test]fn compatible_existing_direct_write_failure_never_claims_old_target_unchanged(){
 let f=Fixture::start("compatible-serial-fail");fs::write(f.root.join("local/a.txt"),b"new direct bytes").unwrap();fs::write(f.remote.join("upload/job/a.txt"),b"old content").unwrap();let e=Engine::default();f.start_job(&e,"direct-error",f.root.join("local"),"/upload/job",true);let s=f.wait_failed(&e,"direct-error");assert_eq!(s["sent"],0);assert_eq!(s["failure"]["commitState"],"unknown","an existing target was truncated and removed; never describe it as untouched");assert!(!f.remote.join("upload/job/a.txt").exists());assert!(f.remote.join("upload/job/later/delete.txt").exists());assert!(!f.remote.join("upload/job/nested/b.txt").exists());e.stop("direct-error").unwrap();
}
fn caught(e:&Engine,id:&str,min:u64)->serde_json::Value{let end=Instant::now()+Duration::from_secs(30);loop{let s=serde_json::to_value(e.status(id).unwrap()).unwrap();assert!(s["failure"].is_null(),"{s}");if s["syncPhase"]=="caught_up"&&s["sent"].as_u64().unwrap()>=min{return s}assert!(Instant::now()<end,"caught-up timeout: {s}");thread::sleep(Duration::from_millis(10));}}
fn until(mut check:impl FnMut()->bool){let end=Instant::now()+Duration::from_secs(30);while !check(){assert!(Instant::now()<end,"generated integration condition timed out");thread::sleep(Duration::from_millis(10));}}
#[test]fn compatible_integration_routes_normal_engine_to_actual_reported_policy(){let f=Fixture::start("compatible-route");fs::write(f.root.join("local/a.txt"),b"small-generated").unwrap();let e=Engine::default();f.start_job(&e,"route",f.root.join("local"),"/upload/job",true);let s=caught(&e,"route",2);assert_eq!(s["syncDecisions"]["version"],3);assert!(s["syncDecisions"]["precision"].as_str().unwrap().contains("2-second tolerance"));e.stop("route").unwrap();}
#[test]fn compatible_integration_watch_directory_comparison_deletion_and_explicit_restart(){
 let f=Fixture::start("compatible-live");let local=f.root.join("local");fs::write(local.join("a.txt"),b"small-generated").unwrap();let target=f.remote.join("upload/job");let e=Engine::default();f.start_job(&e,"live",local.clone(),"/upload/job",true);caught(&e,"live",2);
 let binary=vec![80,75,3,4,0,255,128];fs::write(local.join("nested/new.jar"),&binary).unwrap();caught(&e,"live",3);assert_eq!(fs::read(target.join("nested/new.jar")).unwrap(),binary);
 let changed=b"new longer generated text";fs::write(local.join("nested/b.txt"),changed).unwrap();caught(&e,"live",4);assert_eq!(fs::read(target.join("nested/b.txt")).unwrap(),changed);
 let old=fs::metadata(local.join("nested/b.txt")).unwrap().modified().unwrap();fs::write(local.join("nested/b.txt"),vec![90;changed.len()]).unwrap();fs::File::options().write(true).open(local.join("nested/b.txt")).unwrap().set_times(fs::FileTimes::new().set_modified(old)).unwrap();fs::write(local.join("nested/proof"),b"watch proof").unwrap();caught(&e,"live",5);assert_eq!(fs::read(target.join("nested/b.txt")).unwrap(),changed,"same metadata is deliberately not a content comparison");
 for n in ["new.jar","b.txt","proof"]{fs::remove_file(local.join("nested").join(n)).unwrap();}fs::remove_dir(local.join("nested")).unwrap();until(||!target.join("nested").exists());caught(&e,"live",5);
 e.stop("live").unwrap();assert!(e.status("live").is_err(),"joined stop removes the job owner");fs::write(local.join("after-stop"),b"new after stop").unwrap();thread::sleep(Duration::from_millis(700));assert!(!target.join("after-stop").exists());
 f.start_job(&e,"live",local,"/upload/job",true);caught(&e,"live",1);assert_eq!(fs::read(target.join("after-stop")).unwrap(),b"new after stop");e.stop("live").unwrap();
}
#[test]fn compatible_integration_failure_stops_before_delete_and_no_followup_writes(){let f=Fixture::start("permission");let e=Engine::default();f.start_job(&e,"failure",f.root.join("local"),"/upload/job",true);let failed=f.wait_failed(&e,"failure");assert!(failed["errorCount"].as_u64().unwrap()>0);assert!(f.remote.join("upload/job/later/delete.txt").exists());assert_eq!(failed["sent"],0);fs::write(f.root.join("local/after-error"),b"do not dispatch").unwrap();thread::sleep(Duration::from_millis(700));assert!(!f.remote.join("upload/job/after-error").exists());e.stop("failure").unwrap();}
#[test]fn compatible_integration_cancel_drains_admitted_writes_then_releases_owner(){let f=Fixture::start("compare-parallel-cancel");let e=Engine::default();f.start_job(&e,"cancel",f.root.join("local"),"/upload/job",true);until(||f.root.join("server/batch-held").exists());let release=f.root.join("server/release-batch");let wake=thread::spawn(move||{thread::sleep(Duration::from_millis(100));fs::write(release,b"release generated replies").unwrap();});let summary=e.stop_with_summary("cancel").unwrap();wake.join().unwrap();assert!(summary.known_unreflected);assert!(e.status("cancel").is_err(),"joined stop releases/removes the job owner");assert!(!f.remote.join("upload/job/a.txt").exists());assert!(f.remote.join("upload/job/later/delete.txt").exists());}
